pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testRegression_property() public {
        vm.deal(address(c), 1 ether);
        address recipient = address(0x123);
        uint256 initialContractBalance = address(this).balance;
        bool success;
        try c.withdrawAll(recipient) {
            success = true;
        } catch {
            success = false;
        }
        assertTrue(success, "Owner should be able to withdraw");
    }
}
